CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, pass_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student' CHECK(role IN('student','admin')), created TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT, deletion_reason TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, summary TEXT, price_kes INTEGER NOT NULL CHECK(price_kes>=0), published INTEGER NOT NULL DEFAULT 0, content_status TEXT NOT NULL DEFAULT 'not_written');
CREATE TABLE IF NOT EXISTS lessons(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id), pos INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, is_free INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS quizzes(id INTEGER PRIMARY KEY, lesson_id INTEGER NOT NULL REFERENCES lessons(id), question TEXT NOT NULL, options TEXT NOT NULL, answer INTEGER NOT NULL, explanation TEXT);
CREATE TABLE IF NOT EXISTS enrollments(user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), created TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,course_id));
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, ref TEXT UNIQUE NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), amount_kes INTEGER NOT NULL, provider TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','successful','failed','cancelled','refunded')), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webhook_events(event_id TEXT PRIMARY KEY, received TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS progress(user_id INTEGER NOT NULL REFERENCES users(id), lesson_id INTEGER NOT NULL REFERENCES lessons(id), done_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS quiz_attempts(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, lesson_id INTEGER NOT NULL, score INTEGER NOT NULL, total INTEGER NOT NULL, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS certificates(id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, user_id INTEGER NOT NULL, course_id INTEGER NOT NULL, issued TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,course_id));

CREATE TABLE IF NOT EXISTS assignments(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), lesson_id INTEGER REFERENCES lessons(id), title TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, file_data BLOB NOT NULL, submission_text TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','reviewed','resubmit')), instructor_feedback TEXT DEFAULT '', submitted TEXT DEFAULT CURRENT_TIMESTAMP, reviewed TEXT);
CREATE TABLE IF NOT EXISTS support_tickets(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), subject TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','waiting_student','resolved')), created TEXT DEFAULT CURRENT_TIMESTAMP, updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_replies(id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL REFERENCES support_tickets(id), user_id INTEGER NOT NULL REFERENCES users(id), message TEXT NOT NULL, created TEXT DEFAULT CURRENT_TIMESTAMP);

-- SkillForge learner-outcome and business features
CREATE TABLE IF NOT EXISTS portfolio_projects(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, description TEXT NOT NULL, skills TEXT NOT NULL DEFAULT '', project_url TEXT DEFAULT '', visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN('private','public')), created TEXT DEFAULT CURRENT_TIMESTAMP, updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS opportunities(id INTEGER PRIMARY KEY, title TEXT NOT NULL, organization TEXT NOT NULL, description TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'project', location TEXT DEFAULT 'Remote', apply_url TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')), created_by INTEGER REFERENCES users(id), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS discussions(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER REFERENCES courses(id), parent_id INTEGER REFERENCES discussions(id), body TEXT NOT NULL, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS course_reviews(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), review TEXT NOT NULL DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS business_teams(id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, seats INTEGER NOT NULL CHECK(seats BETWEEN 1 AND 500), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS team_members(team_id INTEGER NOT NULL REFERENCES business_teams(id), email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'invited' CHECK(status IN('invited','active','removed')), created TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(team_id,email));
CREATE TABLE IF NOT EXISTS coupons(code TEXT PRIMARY KEY, percent_off INTEGER NOT NULL CHECK(percent_off BETWEEN 1 AND 90), max_uses INTEGER NOT NULL DEFAULT 100, uses INTEGER NOT NULL DEFAULT 0, expires TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS referrals(id INTEGER PRIMARY KEY, referrer_id INTEGER NOT NULL REFERENCES users(id), code TEXT UNIQUE NOT NULL, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS certificate_status(code TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'valid' CHECK(status IN('valid','revoked')), reason TEXT DEFAULT '', updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, target TEXT NOT NULL, detail TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP);


-- Additional learner-outcome, safety, mentor and sponsored-seat workflows
CREATE TABLE IF NOT EXISTS skill_assessments(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), score INTEGER NOT NULL, total INTEGER NOT NULL, level TEXT NOT NULL CHECK(level IN('foundation','developing','ready')), answers TEXT NOT NULL DEFAULT '{}', created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mentor_clinics(id INTEGER PRIMARY KEY, title TEXT NOT NULL, mentor_name TEXT NOT NULL, description TEXT NOT NULL, starts_at TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 500), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','closed','cancelled')), created_by INTEGER REFERENCES users(id), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clinic_bookings(id INTEGER PRIMARY KEY, clinic_id INTEGER NOT NULL REFERENCES mentor_clinics(id), user_id INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'booked' CHECK(status IN('booked','cancelled','attended')), created TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(clinic_id,user_id));
CREATE TABLE IF NOT EXISTS scholarship_applications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','declined')), admin_note TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, reviewed TEXT);
CREATE TABLE IF NOT EXISTS business_challenges(id INTEGER PRIMARY KEY, title TEXT NOT NULL, organization TEXT NOT NULL, description TEXT NOT NULL, skills TEXT NOT NULL DEFAULT '', deadline TEXT, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')), created_by INTEGER REFERENCES users(id), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS challenge_applications(id INTEGER PRIMARY KEY, challenge_id INTEGER NOT NULL REFERENCES business_challenges(id), user_id INTEGER NOT NULL REFERENCES users(id), message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','shortlisted','declined')), created TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(challenge_id,user_id));
CREATE TABLE IF NOT EXISTS abuse_reports(id INTEGER PRIMARY KEY, reporter_id INTEGER NOT NULL REFERENCES users(id), target_type TEXT NOT NULL, target_id INTEGER NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','reviewing','resolved','dismissed')), admin_note TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, reviewed TEXT);

CREATE TABLE IF NOT EXISTS daily_missions(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), mission_date TEXT NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, target_id INTEGER, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','completed','dismissed')), created TEXT DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, UNIQUE(user_id,mission_date));
CREATE TABLE IF NOT EXISTS learner_goals(user_id INTEGER PRIMARY KEY REFERENCES users(id), weekly_target INTEGER NOT NULL DEFAULT 3 CHECK(weekly_target BETWEEN 1 AND 14), career_goal TEXT DEFAULT '', updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS milestone_awards(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), milestone_key TEXT NOT NULL, title TEXT NOT NULL, awarded TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,milestone_key));
CREATE TABLE IF NOT EXISTS learning_events(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, target_type TEXT DEFAULT '', target_id INTEGER, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_feedback(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES portfolio_projects(id), reviewer_id INTEGER NOT NULL REFERENCES users(id), feedback TEXT NOT NULL, rubric_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'visible' CHECK(status IN('visible','hidden','removed')), created TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id,reviewer_id));
CREATE TABLE IF NOT EXISTS study_groups(id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN('private','public')), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS study_group_members(group_id INTEGER NOT NULL REFERENCES study_groups(id), user_id INTEGER NOT NULL REFERENCES users(id), role TEXT NOT NULL DEFAULT 'member' CHECK(role IN('owner','member')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','removed')), joined TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS weekly_challenges(id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, rubric TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','open','closed')), created_by INTEGER REFERENCES users(id), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS weekly_challenge_submissions(id INTEGER PRIMARY KEY, challenge_id INTEGER NOT NULL REFERENCES weekly_challenges(id), user_id INTEGER NOT NULL REFERENCES users(id), project_url TEXT DEFAULT '', submission_text TEXT NOT NULL, score INTEGER, feedback TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','reviewed','withdrawn')), created TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(challenge_id,user_id));
CREATE TABLE IF NOT EXISTS referral_attributions(id INTEGER PRIMARY KEY, referrer_id INTEGER NOT NULL REFERENCES users(id), referred_user_id INTEGER NOT NULL UNIQUE REFERENCES users(id), referral_code TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'registered' CHECK(status IN('registered','qualified','rejected')), qualifying_payment_ref TEXT UNIQUE, created TEXT DEFAULT CURRENT_TIMESTAMP, reviewed TEXT);
CREATE TABLE IF NOT EXISTS reward_ledger(id INTEGER PRIMARY KEY, referral_id INTEGER NOT NULL REFERENCES referral_attributions(id), referrer_id INTEGER NOT NULL REFERENCES users(id), amount_kes INTEGER NOT NULL CHECK(amount_kes>0), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','redeemed','reversed','rejected')), reason TEXT DEFAULT '', payment_ref TEXT UNIQUE, created TEXT DEFAULT CURRENT_TIMESTAMP, updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS career_goals(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), goal TEXT NOT NULL, target_date TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','achieved','paused')), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS career_applications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), organization TEXT NOT NULL, role_title TEXT NOT NULL, source_url TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'saved' CHECK(status IN('saved','applied','interview','offer','rejected','withdrawn')), follow_up TEXT, notes TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_preferences(user_id INTEGER PRIMARY KEY REFERENCES users(id), in_app INTEGER NOT NULL DEFAULT 1, email INTEGER NOT NULL DEFAULT 0, push INTEGER NOT NULL DEFAULT 0, weekly_digest INTEGER NOT NULL DEFAULT 1, reminders INTEGER NOT NULL DEFAULT 1, quiet_start TEXT DEFAULT '21:00', quiet_end TEXT DEFAULT '08:00', timezone TEXT DEFAULT 'Africa/Nairobi', updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_queue(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, due_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','sent','failed','cancelled')), channel TEXT NOT NULL DEFAULT 'in_app', dedupe_key TEXT UNIQUE, created TEXT DEFAULT CURRENT_TIMESTAMP, sent_at TEXT);
CREATE TABLE IF NOT EXISTS learner_benefits(id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, benefit_type TEXT NOT NULL DEFAULT 'resource', status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','expired')), starts_at TEXT, ends_at TEXT, created_by INTEGER REFERENCES users(id), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS benefit_redemptions(id INTEGER PRIMARY KEY, benefit_id INTEGER NOT NULL REFERENCES learner_benefits(id), user_id INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'claimed' CHECK(status IN('claimed','used','cancelled')), created TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(benefit_id,user_id));
CREATE INDEX IF NOT EXISTS idx_progress_user_done ON progress(user_id,done_at);
CREATE INDEX IF NOT EXISTS idx_learning_events_created ON learning_events(created,user_id);
CREATE INDEX IF NOT EXISTS idx_referral_status ON referral_attributions(status,created);
CREATE INDEX IF NOT EXISTS idx_notification_due ON notification_queue(status,due_at);


-- Integrated career marketplace, employer verification, instructor applications and membership requests.
-- All additions are additive and preserve existing learner/payment records.
CREATE TABLE IF NOT EXISTS freelance_gigs(id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, description TEXT NOT NULL, skills TEXT NOT NULL DEFAULT '', budget_min_kes INTEGER NOT NULL DEFAULT 0, budget_max_kes INTEGER NOT NULL DEFAULT 0, deadline TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','open','closed','rejected')), created TEXT DEFAULT CURRENT_TIMESTAMP, reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS freelance_proposals(id INTEGER PRIMARY KEY, gig_id INTEGER NOT NULL REFERENCES freelance_gigs(id), freelancer_id INTEGER NOT NULL REFERENCES users(id), cover_note TEXT NOT NULL, proposed_budget_kes INTEGER NOT NULL DEFAULT 0, timeline_days INTEGER NOT NULL DEFAULT 7, status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','shortlisted','accepted','declined','withdrawn')), created TEXT DEFAULT CURRENT_TIMESTAMP, updated TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(gig_id,freelancer_id));
CREATE TABLE IF NOT EXISTS employer_profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id), organization TEXT NOT NULL, website TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', verification_status TEXT NOT NULL DEFAULT 'pending' CHECK(verification_status IN('pending','verified','rejected')), created TEXT DEFAULT CURRENT_TIMESTAMP, reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS opportunity_applications(id INTEGER PRIMARY KEY, opportunity_id INTEGER NOT NULL REFERENCES opportunities(id), user_id INTEGER NOT NULL REFERENCES users(id), cover_note TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','reviewing','shortlisted','rejected','withdrawn')), created TEXT DEFAULT CURRENT_TIMESTAMP, updated TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(opportunity_id,user_id));
CREATE TABLE IF NOT EXISTS instructor_applications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expertise TEXT NOT NULL, experience TEXT NOT NULL, sample_url TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')), admin_note TEXT NOT NULL DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS membership_requests(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), plan_code TEXT NOT NULL CHECK(plan_code IN('all_access_monthly','career_bundle','business_team')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','contacted','activated','declined','cancelled')), quoted_price_kes INTEGER, notes TEXT NOT NULL DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, updated TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,plan_code,status));

-- Skillora excellence modules: public skill passport, practice lab submissions, and course quality feedback.
CREATE TABLE IF NOT EXISTS skill_passports(user_id INTEGER PRIMARY KEY REFERENCES users(id), share_token TEXT UNIQUE, public_enabled INTEGER NOT NULL DEFAULT 0 CHECK(public_enabled IN(0,1)), updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS practice_lab_submissions(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), lab_key TEXT NOT NULL, answer_text TEXT NOT NULL, project_url TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','reviewed','resubmit')), reviewer_feedback TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, updated TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,lab_key));
CREATE TABLE IF NOT EXISTS course_quality_reports(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), category TEXT NOT NULL CHECK(category IN('incorrect_content','outdated_content','accessibility','broken_exercise','other')), details TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','reviewing','resolved','dismissed')), admin_note TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, reviewed TEXT);
CREATE INDEX IF NOT EXISTS idx_quality_reports_status ON course_quality_reports(status,created);
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY, message TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT 'info' CHECK(level IN('info','success','warning')), active INTEGER NOT NULL DEFAULT 1, created_by INTEGER REFERENCES users(id), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_mpesa(ref TEXT PRIMARY KEY, checkout_request_id TEXT UNIQUE, merchant_request_id TEXT, phone_last4 TEXT, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daily_checkins(user_id INTEGER NOT NULL REFERENCES users(id), day TEXT NOT NULL, focus TEXT NOT NULL DEFAULT 'lesson', created TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS review_cards(user_id INTEGER NOT NULL REFERENCES users(id), quiz_id INTEGER NOT NULL REFERENCES quizzes(id), box INTEGER NOT NULL DEFAULT 1, due TEXT NOT NULL, last_reviewed TEXT, correct_count INTEGER NOT NULL DEFAULT 0, wrong_count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,quiz_id));
CREATE TABLE IF NOT EXISTS exercise_completions(user_id INTEGER NOT NULL REFERENCES users(id), exercise_key TEXT NOT NULL, completed TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,exercise_key));
CREATE TABLE IF NOT EXISTS cohorts(id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', course_id INTEGER REFERENCES courses(id), starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, capacity INTEGER NOT NULL DEFAULT 30 CHECK(capacity BETWEEN 2 AND 500), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','closed','cancelled')), created_by INTEGER REFERENCES users(id), created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cohort_members(cohort_id INTEGER NOT NULL REFERENCES cohorts(id), user_id INTEGER NOT NULL REFERENCES users(id), joined TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(cohort_id,user_id));
CREATE TABLE IF NOT EXISTS learner_outcomes(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN('first_client','job_interview','job_offer','new_job','business_started','income_increase')), note TEXT NOT NULL DEFAULT '', evidence_url TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','verified','rejected')), created TEXT DEFAULT CURRENT_TIMESTAMP, reviewed_by INTEGER REFERENCES users(id), reviewed TEXT);
CREATE TABLE IF NOT EXISTS user_contacts(user_id INTEGER PRIMARY KEY REFERENCES users(id), phone TEXT NOT NULL DEFAULT '', verified INTEGER NOT NULL DEFAULT 0, sms_opt_in INTEGER NOT NULL DEFAULT 0, otp_hash TEXT, otp_exp INTEGER, otp_tries INTEGER NOT NULL DEFAULT 0, updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reminder_log(user_id INTEGER NOT NULL REFERENCES users(id), day TEXT NOT NULL, channel TEXT NOT NULL DEFAULT 'sms', created TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,day,channel));
CREATE TABLE IF NOT EXISTS ai_usage(day TEXT NOT NULL, user_id INTEGER NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(day,user_id));

CREATE TABLE IF NOT EXISTS payment_mpesa(ref TEXT PRIMARY KEY, checkout_request_id TEXT, merchant_request_id TEXT, phone_last4 TEXT);
CREATE TABLE IF NOT EXISTS payment_paystack(ref TEXT PRIMARY KEY, access_code TEXT, authorization_url TEXT, paystack_ref TEXT);
CREATE TABLE IF NOT EXISTS db_meta(key TEXT PRIMARY KEY, value TEXT NOT NULL, updated TEXT DEFAULT CURRENT_TIMESTAMP);
